import json, urllib.request, urllib.parse
def get(u):
    with urllib.request.urlopen(u, timeout=30) as r:
        return json.load(r)
try:
    p = get("https://pypi.org/pypi/archy/json")
    print("pypi latest:", p["info"]["version"])
    files = get("https://pypi.org/pypi/archy/0.53.4/json")["urls"]
    print("0.53.4 files:", sorted(f["packagetype"] for f in files))
except Exception as e:
    print("pypi error:", e)
try:
    q = urllib.parse.quote("archy")
    r = get(f"https://registry.modelcontextprotocol.io/v0/servers?search={q}")
    for s in r.get("servers", []):
        sv = s.get("server", s)
        meta = s.get("_meta", {}).get("io.modelcontextprotocol.registry/official", {})
        print("registry:", sv.get("name"), sv.get("version"), "isLatest=", meta.get("isLatest"))
except Exception as e:
    print("registry error:", e)

